type AnalytifyStatusProps = {
  className?: string;
  status?: "Disabled" | "Unavailable";
};

function AnalytifyStatus({ className, status = "Disabled" }: AnalytifyStatusProps) {
  const isUnavailable = status === "Unavailable";
  return (
    <div className={className || "bg-[var(--v2-color-surface-raised,#182019)] content-stretch flex gap-[var(--v2-space-2,8px)] items-center overflow-clip px-[var(--v2-space-3,12px)] py-[var(--v2-space-1,4px)] relative rounded-[var(--v2-radius-pill,999px)]"} id={isUnavailable ? "node-43_1725" : "node-43_1704"}>
      <p className="[word-break:break-word] font-['Outfit:SemiBold'] font-semibold leading-[20px] relative shrink-0 text-[14px] text-[color:var(--v2-color-text-muted,#a2ada6)] whitespace-nowrap" id={isUnavailable ? "node-43_1724" : "node-43_1703"}>
        {isUnavailable ? "Unavailable" : "Disabled"}
      </p>
    </div>
  );
}

